inline uint8_t rs01_byte(size_t offset, uint8_t stock) {
  if (offset >= 0x3c && offset < 0x3c + sizeof(RS01_RS_VECTOR)) return RS01_RS_VECTOR[offset - 0x3c];
  if (offset >= 0x5df8 && offset < 0x5df8 + sizeof(RS01_RS_BOOT_HOOK)) return RS01_RS_BOOT_HOOK[offset - 0x5df8];
  if (offset >= 0x53ae && offset < 0x53ae + sizeof(RS01_RS_UART_HOOK)) return RS01_RS_UART_HOOK[offset - 0x53ae];
  if (offset >= 0x5e88 && offset < 0x5e88 + sizeof(RS01_RS_MAIN_HOOK)) return RS01_RS_MAIN_HOOK[offset - 0x5e88];
  if (offset >= 0x1cf4 && offset < 0x1cf4 + sizeof(RS01_RS_PARSER_HOOK)) return RS01_RS_PARSER_HOOK[offset - 0x1cf4];
  if (offset >= 0x4e36 && offset < 0x4e36 + sizeof(RS01_RS_RX_RESET_HOOK)) return RS01_RS_RX_RESET_HOOK[offset - 0x4e36];
  if (offset >= 0x3bc8 && offset < 0x3bc8 + sizeof(RS01_RS_SPEED_HOOK)) return RS01_RS_SPEED_HOOK[offset - 0x3bc8];
  if (offset >= 0x48d8 && offset < 0x48d8 + sizeof(RS01_RS_OUTPUT_HOOK)) return RS01_RS_OUTPUT_HOOK[offset - 0x48d8];
  if (offset >= 0x340c && offset < 0x340c + sizeof(RS01_RS_COMPLETE_HOOK)) return RS01_RS_COMPLETE_HOOK[offset - 0x340c];
  if (offset >= 0x6c00 && offset < 0x6c00 + sizeof(RS01_RESET_SPEED)) return RS01_RESET_SPEED[offset - 0x6c00];
  return cl01_byte(offset,stock);
}
// The caller verifies exact CL01 input and RS01 output application hashes.
inline bool apply_reset_speed(uint8_t *image, size_t size) {
  const uint8_t vector[]={0xc1,0x73,0x00,0x08}, main[]={0xfd,0xf7,0xe6,0xf9};
  const uint8_t parser[]={0xf0,0xb5,0x8c,0x46,0x01,0x79,0x04,0x68};
  const uint8_t rx_init[]={0x00,0xf0,0xa9,0xfc};
  const uint8_t complete[]={0xff,0xf7,0x60,0xfe};
  const uint8_t speed[]={0x21,0x6a,0x60,0x68}, output[]={0x10,0xb5,0x07,0x4c,0x00,0x22,0x06,0x4b};
  if (!image || size!=IMAGE_SIZE || std::memcmp(image+0x3c,vector,sizeof(vector)) ||
      std::memcmp(image+0x5e88,main,sizeof(main)) || std::memcmp(image+0x1cf4,parser,sizeof(parser)) ||
      std::memcmp(image+0x4e36,rx_init,sizeof(rx_init)) ||
      std::memcmp(image+0x3bc8,speed,sizeof(speed)) ||
      std::memcmp(image+0x340c,complete,sizeof(complete)) ||
      std::memcmp(image+0x48d8,output,sizeof(output)) ||
      std::memcmp(image+0x53ae,CL01_HOOK,sizeof(CL01_HOOK)) ||
      std::memcmp(image+0x5df8,CL01_BOOT_HOOK,sizeof(CL01_BOOT_HOOK)) ||
      std::memcmp(image+0x6400,CL01_CHILD_LOCK,sizeof(CL01_CHILD_LOCK))) return false;
  for (size_t i=0x6c00; i<IMAGE_SIZE; ++i) if (image[i]!=255) return false;
  std::memcpy(image+0x3c,RS01_RS_VECTOR,sizeof(RS01_RS_VECTOR));
  std::memcpy(image+0x5df8,RS01_RS_BOOT_HOOK,sizeof(RS01_RS_BOOT_HOOK));
  std::memcpy(image+0x53ae,RS01_RS_UART_HOOK,sizeof(RS01_RS_UART_HOOK));
  std::memcpy(image+0x5e88,RS01_RS_MAIN_HOOK,sizeof(RS01_RS_MAIN_HOOK));
  std::memcpy(image+0x1cf4,RS01_RS_PARSER_HOOK,sizeof(RS01_RS_PARSER_HOOK));
  std::memcpy(image+0x4e36,RS01_RS_RX_RESET_HOOK,sizeof(RS01_RS_RX_RESET_HOOK));
  std::memcpy(image+0x3bc8,RS01_RS_SPEED_HOOK,sizeof(RS01_RS_SPEED_HOOK));
  std::memcpy(image+0x48d8,RS01_RS_OUTPUT_HOOK,sizeof(RS01_RS_OUTPUT_HOOK));
  std::memcpy(image+0x340c,RS01_RS_COMPLETE_HOOK,sizeof(RS01_RS_COMPLETE_HOOK));
  std::memcpy(image+0x6c00,RS01_RESET_SPEED,sizeof(RS01_RESET_SPEED));
  return true;
}
